# Fold sub-varieties into their base so we never pair a thing with itself.
canon_map <- c(
  "White chocolate" = "Chocolate",
  "Dark chocolate" = "Chocolate",
  "Milk chocolate" = "Chocolate",
  "Ruby chocolate" = "Chocolate",
  "Ganache" = "Chocolate",
  "Cacao nib" = "Chocolate",
  "Salted caramel" = "Caramel",
  "Blood orange" = "Orange",
  "Black sesame" = "Sesame",
  "Peanut butter" = "Peanut"
)
canonise <- function(x) unname(coalesce(canon_map[x], x))

# find_ings(text): canonical ingredients whose pattern is present in the text.
find_ings <- function(text) {
  text <- str_to_lower(replace_na(as.character(text), ""))
  hit  <- str_detect(text, regex(gazetteer$pattern, ignore_case = TRUE))
  unique(canonise(gazetteer$ingredient[hit]))
}

# family of a (possibly canonised) ingredient
fam_lookup <- deframe(distinct(gazetteer, ingredient, family))
ing_family <- function(x) unname(fam_lookup[x])
